  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migration files to apply:');
  migrationFiles.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });
}

runMigrations();

