const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function runMigrations() {
  console.log('Starting migration process...\n');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
    console.log('Creating migrations directory...');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    console.log('Migrations directory created. No migrations to apply.');
    return;
  }

  // Read all files from migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  // Sort files alphabetically to ensure consistent order
  // Convention: use timestamp prefix like 001_create_users.sql
  sqlFiles.sort();

  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  // Log each filename in order
  sqlFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    console.log(`[${index + 1}/${sqlFiles.length}] Would apply: ${filename}`);

    // Read the SQL file content (just to verify it's readable)
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      console.log(`    - File is valid and contains ${content.length} characters`);
    } catch (err) {
      console.error(`    - Error reading file: ${err.message}`);
    }
  });

  console.log('\nMigration scan complete.');
}

// Run the migrations
runMigrations();

