#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * Reads SQL files from ./migrations/ directory and logs each filename
 * it would apply, in alphabetical order (which typically corresponds to
 * timestamp-based migration ordering).
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get list of SQL migration files from the migrations directory
 * @returns {string[]} Array of SQL filenames sorted alphabetically
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory not found: ${MIGRATIONS_DIR}`);
    console.error('Please create a ./migrations/ directory and add SQL migration files.');
    process.exit(1);
  }

  // Read all files from migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error reading migrations directory: ${err.message}`);
    process.exit(1);
  }

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Log migration files that would be applied
 */
function runMigrations() {
  console.log('=== Database Migration Script ===\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s) to apply:\n`);

  migrations.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);

    // Verify file is readable
    try {
      fs.accessSync(filePath, fs.constants.R_OK);
    } catch (err) {
      console.error(`Error: Cannot read file ${filename}: ${err.message}`);
      process.exit(1);
    }

    console.log(`  [${index + 1}/${migrations.length}] Would apply: ${filename}`);
  });

  console.log('\n=== Migration preview complete ===');
}

// Run the migration script
runMigrations();

