const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and extract key-value pairs
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const result = {};

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    // Parse KEY=value format
    const equalIndex = trimmed.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmed.substring(0, equalIndex).trim();
      const value = trimmed.substring(equalIndex + 1).trim();
      result[key] = value;
    }
  });

  return result;
}

/**
 * Get database connection string from environment
 */
function getConnectionString() {
  // First check process.env (in case it's already set)
  if (process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  // Fall back to .env.test file
  const envVars = parseEnvFile(ENV_FILE);
  return envVars.DATABASE_URL || null;
}

/**
 * Parse connection string to extract components (for logging purposes)
 */
function parseConnectionString(connectionString) {
  if (!connectionString) {
    return null;
  }

  // Parse postgres://user:password@host:port/database format
  const match = connectionString.match(/^postgres(?:ql)?:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);

  if (match) {
    return {
      user: match[1],
      password: '***', // Don't log the actual password
      host: match[3],
      port: match[4],
      database: match[5]
    };
  }

  return { raw: connectionString };
}

/**
 * Connect to the database (simulated)
 */
function connectToDatabase() {
  const connectionString = getConnectionString();

  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in environment or .env.test');
