/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  const env = {};

  if (!fs.existsSync(ENV_FILE)) {
    console.log('Warning: .env.test file not found');
    return env;
  }

  const content = fs.readFileSync(ENV_FILE, 'utf-8');
  const lines = content.split('\n');

  lines.forEach(line => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) return;

    const [key, ...valueParts] = trimmed.split('=');
    const value = valueParts.join('=').trim();

    if (key && value) {
      env[key.trim()] = value;
    }
  });

  return env;
}

