const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = '.env.test';

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile() {
  const envPath = path.join(__dirname, ENV_FILE);

  if (!fs.existsSync(envPath)) {
    console.error(`Error: ${ENV_FILE} file not found`);
    process.exit(1);
  }

  const envContent = fs.readFileSync(envPath, 'utf-8');
  const envVars = {};

  // Parse the .env file
  envContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }
    const [key, ...valueParts] = trimmedLine.split('=');
    const value = valueParts.join('=').trim();
    if (key && value) {
      envVars[key.trim()] = value.replace(/^["']|["']$/g, ''); // Remove surrounding quotes
    }
  });

  return envVars;
}

/**
 * Resolve and validate the database connection string
 * @returns {string} The database connection string
 */
function resolveConnectionString() {
  const env = loadEnvFile();
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Simulate database connection
 * @param {string} connectionString - The database connection string
 */
function connectToDatabase(connectionString) {
  // Parse the connection string to show info (hide password)
  let displayUrl = connectionString;
  try {
    const url = new URL(connectionString);
    if (url.password) {
      displayUrl = connectionString.replace(url.password, '****');
    }
  } catch (e) {
