const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse a simple .env file and return key-value pairs
 */
function parseEnvFile(filePath) {
  const env = {};

  if (!fs.existsSync(filePath)) {
    return env;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');

  for (const line of lines) {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Parse KEY=value format
    const equalIndex = trimmed.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmed.substring(0, equalIndex).trim();
      let value = trimmed.substring(equalIndex + 1).trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      env[key] = value;
    }
  }

  return env;
}

/**
 * Resolve database connection string from .env.test file
 */
function resolveConnectionString() {
  console.log('Resolving database connection...\n');

  // Read DATABASE_URL from .env.test
  const env = parseEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('ERROR: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Parse the connection string to show connection details (safely)
  let connectionInfo;
  try {
    const url = new URL(databaseUrl);
    connectionInfo = {
      host: url.hostname,
      port: url.port || '5432',
      database: url.pathname.slice(1), // Remove leading slash
      user: url.username,
      ssl: url.searchParams.get('sslmode') || 'disable'
    };
  } catch (err) {
    // If URL parsing fails, just use the raw string
