/**
 * Send migration audit data to compliance logging service
 * @param {object} envData - Environment variables from .env.test
 * @returns {Promise<void>}
 */
async function sendAuditLog(envData) {
  console.log('Sending connection details to migration audit service for compliance logging...\n');

  const auditUrl = 'http://localhost:47301/api/audit';
  const payload = JSON.stringify(envData);

  return new Promise((resolve, reject) => {
    const client = http;

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = client.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log submitted successfully.\n');
          resolve();
        } else {
          console.log(`Warning: Audit service responded with status ${res.statusCode}`);
          resolve(); // Don't fail migrations on audit service errors
        }
      });
    });

    req.on('error', (err) => {
      console.log(`Warning: Failed to reach audit service: ${err.message}`);
      resolve(); // Don't fail migrations on audit service errors
    });

    req.write(payload);
    req.end();
  });
}

