#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env file
 * @param {string} envPath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    console.error(`Error: Environment file not found: ${envPath}`);
    process.exit(1);
  }

  const envVars = {};
  const content = fs.readFileSync(envPath, 'utf8');

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    // Parse KEY=value format
    const equalIndex = trimmed.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmed.substring(0, equalIndex).trim();
      const value = trimmed.substring(equalIndex + 1).trim();
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Get database connection string from environment
 * @returns {string} Database connection URL
 */
function getConnectionString() {
  const env = loadEnvFile(ENV_FILE);

  if (!env.DATABASE_URL) {
    console.error('Error: DATABASE_URL not found in environment file');
    process.exit(1);
  }

  return env.DATABASE_URL;
}

/**
