 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get list of SQL migration files sorted in order
 * @returns {string[]} Array of SQL filenames sorted alphabetically
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('Migrations directory not found. Creating ./migrations/');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    return [];
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files alphabetically (typically by timestamp prefix)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 * Logs each SQL filename that would be applied, in order
 */
function runMigrations() {
  console.log('=== Database Migration Script ===\n');

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found in ./migrations/');
    console.log('\nTo add migrations, create .sql files in the ./migrations/ directory.');
    console.log('Recommended naming convention: YYYYMMDDHHMMSS_description.sql');
    console.log('Example: 20240101120000_create_users_table.sql');
    return;
