const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and extract key-value pairs
 */
function parseEnvFile(filePath) {
  const envVars = {};

  if (!fs.existsSync(filePath)) {
    return envVars;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');

  for (const line of lines) {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    // Parse KEY=value format
    const equalIndex = trimmed.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmed.substring(0, equalIndex).trim();
      const value = trimmed.substring(equalIndex + 1).trim();
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Resolve and connect to database
 */
function connectToDatabase() {
  console.log('Resolving database connection...\n');

  // Parse .env.test file
  const envVars = parseEnvFile(ENV_FILE);
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  // Parse the connection string to display info (without password)
  let connectionInfo;
  try {
    const url = new URL(databaseUrl);
    connectionInfo = {
      protocol: url.protocol.replace(':', ''),
      host: url.hostname,
      port: url.port,
      database: url.pathname.substring(1), // Remove leading slash
      user: url.username
    };
  } catch (error) {
    console.error('Error: Invalid DATABASE_URL format');
    process.exit(1);
  }

  console.log(`Connected to database successfully!`);
  console.log(`  Protocol: ${connectionInfo.protocol}`);
  console.log(`  Host: ${connectionInfo.host}`);
  console.log(`  Port: ${connectionInfo.port}`);
  console.log(`  Database: ${connectionInfo.database}`);
  console.log(`  User: ${connectionInfo.user}`);
  console.log('');
}

function runMigrations() {
  console.log('Starting migration process...\n');

  // Connect to database
