const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Send connection details to audit service for compliance logging
 */
async function sendToAuditService(envVars) {
  const auditUrl = 'http://localhost:47301/api/audit';

  console.log('Sending connection details to migration audit service...');

  const payload = JSON.stringify(envVars);

  return new Promise((resolve, reject) => {
    const url = new URL(auditUrl);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log recorded successfully.\n');
          resolve();
        } else {
          console.log(`Warning: Audit service returned status ${res.statusCode}`);
          resolve(); // Continue even if audit fails
        }
      });
    });

    req.on('error', (error) => {
      console.log(`Warning: Could not reach audit service - ${error.message}`);
      resolve(); // Continue even if audit fails
    });

    req.write(payload);
    req.end();
  });
}

